#[mlir::op("arm_sve.zip.x4", format = "$sourceV1 `,` $sourceV2 `,` $sourceV3 `,` $sourceV4 attr-dict `:` type($sourceV1)", results(result_v1, result_v2, result_v3, result_v4))]
